import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.EDt1A0Ag.js";const c=JSON.parse('{"title":"关于我们 | 全球机场 (AirportMatrix) 评测实验室","description":"AirportMatrix 实验室简介、团队专业背景、独立编辑准则与网络工程测试使命。","frontmatter":{"title":"关于我们 | 全球机场 (AirportMatrix) 评测实验室","description":"AirportMatrix 实验室简介、团队专业背景、独立编辑准则与网络工程测试使命。"},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1791871482000}'),e={name:"about.md"};function l(n,r,s,d,g,h){return a(),o("div",null,[...r[0]||(r[0]=[i('<h1 id="🌿-关于-airportmatrix-评测实验室" tabindex="-1">🌿 关于 AirportMatrix 评测实验室 <a class="header-anchor" href="#🌿-关于-airportmatrix-评测实验室" aria-label="Permalink to &quot;🌿 关于 AirportMatrix 评测实验室&quot;">​</a></h1><p>欢迎访问 <strong>全球机场 · 森林知识屋 (AirportMatrix)</strong>。我们是一个由网络工程师、分布式系统开发者与海外学术研究者自发组建的独立网络连通性评测与协议研究实验室。</p><hr><h2 id="🎯-我们的使命与初衷" tabindex="-1">🎯 我们的使命与初衷 <a class="header-anchor" href="#🎯-我们的使命与初衷" aria-label="Permalink to &quot;🎯 我们的使命与初衷&quot;">​</a></h2><p>在跨境网络访问与学术科研领域，用户长期面临信息不对称与虚假宣传的困扰：</p><ul><li><strong>劣质中继充当内网专线</strong>：大量服务商以廉价公网中转冒充高成本 IPLC/IEPL 专线，在晚高峰骨干网拥塞时丢包率骤增至 30% 以上。</li><li><strong>流媒体与 AI 解锁虚标</strong>：声称原生住宅双 ISP IP，实际为高风险数据中心机房 IP，导致 ChatGPT 频繁遭遇 <code>Access Denied</code> 或风控降智。</li><li><strong>商业水军与无底线吹捧</strong>：评测内容高度同质化，掩盖晚高峰限速、月付跑路、退款无门等关键风险。</li></ul><p><strong>AirportMatrix 实验室的创立目标</strong>：构建一套透明、量化、基于真实全天候多运营商实测的评测标准，以网络工程视角拆解底层链路技术，帮助科研人员、出海工程师、跨境电商从业者与海外留学生挑选安全、稳定、高性价比的网络工具。</p><hr><h2 id="🔬-团队专业背景" tabindex="-1">🔬 团队专业背景 <a class="header-anchor" href="#🔬-团队专业背景" aria-label="Permalink to &quot;🔬 团队专业背景&quot;">​</a></h2><p>我们的核心成员均拥有 8 年以上网络工程与云计算架构实战经验：</p><ul><li><strong>首席网络架构师（Linus K.）</strong>：拥有 CCIE（Cisco Certified Internetwork Expert）认证，前跨国企业 SD-WAN 骨干网络运维主管，主导本实验室的 BGP 选路路由分析、晚高峰抖动压测与专线拓扑逆向工程。</li><li><strong>协议与风控研究员（Elena S.）</strong>：专注于 TLS 1.3 指纹、ECH 扩展、QUIC/HTTP3 传输协议特征及海外安全网关（Cloudflare WAF / Akamai / Datadome）IP 纯净度风控算法研究。</li><li><strong>自动化测试工程师（David T.）</strong>：负责维护本实验室自研的 <code>MAI-TEST-BOT</code> 分布式自动化测速探针集群，编写无头浏览器自动化验证脚本。</li></ul><hr><h2 id="🛡️-编辑独立性与准则" tabindex="-1">🛡️ 编辑独立性与准则 <a class="header-anchor" href="#🛡️-编辑独立性与准则" aria-label="Permalink to &quot;🛡️ 编辑独立性与准则&quot;">​</a></h2><p>我们恪守以下四条铁律，确保评测报告的公信力与技术严谨性：</p><ol><li><strong>自费订阅与盲测机制</strong>：所有纳入深度评测的服务商，均由测试人员通过公开渠道匿名自费购买标准套餐，拒绝任何特殊优待节点或定制“专属测速白名单”。</li><li><strong>拒绝付费篡改评测结论</strong>：我们坚决不接受任何厂商通过付费、充值或赞助要求修改、删除评测差评，或虚标测速成绩的行为。</li><li><strong>数据优先与原始日志留存</strong>：每份评测数据均附带测试时间戳、运营商环境、测试工具版本与丢包率分布图，确保数据可复现、可溯源。</li><li><strong>定期复测与淘汰机制</strong>：网络服务质量具有时效性。我们建立季度巡检与重大事件（如断缆、敏感期）动态复测体系，对连续出现降速或失联的服务商即时下调评级。</li></ol><hr><h2 id="🏗️-评测基础设施" tabindex="-1">🏗️ 评测基础设施 <a class="header-anchor" href="#🏗️-评测基础设施" aria-label="Permalink to &quot;🏗️ 评测基础设施&quot;">​</a></h2><p>为了杜绝单点测试的片面性，我们在中国大陆主要骨干网络枢纽节点部署了自建测试探针：</p><ul><li><strong>电信骨干节点</strong>：上海电信 CN2/163 出口、广州电信骨干出口；</li><li><strong>联通骨干节点</strong>：北京联通、山东联通 AS4837/AS9929 出口；</li><li><strong>移动骨干节点</strong>：广东移动、江苏移动 CMI 出口；</li><li><strong>测试时间窗口</strong>：覆盖平日低峰期（10:00 - 16:00）、晚高峰拥塞期（20:00 - 23:30）以及节假日负载波动期。</li></ul><p>详细测试方法与量化指标请查阅 <a href="/methodology">评测方法论与质检标准</a>。</p><hr><h2 id="📬-联系方式与勘误反馈" tabindex="-1">📬 联系方式与勘误反馈 <a class="header-anchor" href="#📬-联系方式与勘误反馈" aria-label="Permalink to &quot;📬 联系方式与勘误反馈&quot;">​</a></h2><p>我们鼓励读者、同行专家与技术社区监督我们的评测报告。若您在阅读过程中发现任何数据偏差、品牌配置变更或链接失效，欢迎通过以下渠道与实验室联系：</p><ul><li><strong>官方邮箱</strong>：<code>admin@airportmatrix.blog</code></li><li><strong>代码仓库</strong>：<a href="https://github.com" target="_blank" rel="noreferrer">GitHub Issues</a></li><li><strong>勘误承诺</strong>：在收到有效技术证据（测速截图、路由追踪 MTR 日志）后，我们将在 48 小时内核实并发布勘误公告。</li></ul>',24)])])}const u=t(e,[["render",l]]);export{c as __pageData,u as default};
